<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import {Session} from '$lib/stores';
 import {createStaffClient,can,type StaffClient} from './staff-client';
 let client:StaffClient|undefined,epoch=0,closed=false;let operations=$state<any>(),error=$state(''),pending=$state(false);
 $effect(()=>{const session=$Session;untrack(()=>{epoch++;client?.dispose();client=undefined;operations=undefined;error='';pending=false;if(session?.identity?.id)void load();});});
 onDestroy(()=>{closed=true;epoch++;client?.dispose();});
 async function load(){if(pending||!$Session?.identity?.id)return;const n=epoch,session=$Session,assert=()=>{if(closed||n!==epoch||session!==$Session)throw Error('Account changed');};pending=true;error='';try{client=client??await createStaffClient(session.identity.id,assert);assert();if(!can(client.authority,'operations.read',true))throw Error('Your account does not have operations read access.');const result=await client.read('/staff/operations');assert();if(result.scope!=='native-operations-read-only'||!Array.isArray(result.pendingPublications)||!Array.isArray(result.blockedSchedules))throw Error('The overview could not be checked.');operations=result;}catch(cause){try{assert();operations=undefined;error=cause instanceof Error?cause.message:'The overview could not be loaded.';}catch{}}finally{try{assert();pending=false;}catch{}}}
</script>
<svelte:head><title>Operations overview</title></svelte:head>
<section class="space-y-5">
 <h1 class="text-2xl font-semibold">Operations overview</h1><p>Read-only status for this instance. There are no publication retry, key-management, peer-management or storage-repair buttons here.</p><a class="underline" href="/staff">Staff home</a>
 <button class="rounded border p-2" disabled={pending||!$Session?.identity?.id} onclick={load}>Refresh status</button>
 {#if pending}<p role="status">Checking services and pending work…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}
 {#if operations}<section class="rounded border p-4 space-y-2"><h2 class="text-xl font-semibold">Services</h2><dl class="grid grid-cols-2 gap-2"><dt>Database</dt><dd>{operations.health.database}</dd><dt>Original service schema</dt><dd>{operations.health.protocolSchemaReady?'Ready':'Not ready — source operations may be unavailable'}</dd><dt>Service lifecycle</dt><dd>{operations.health.draining?'Draining — wait for the operator':'Accepting work'}</dd><dt>Registration</dt><dd>{operations.health.registrationEnabled?'Enabled':'Closed'}</dd><dt>Account email</dt><dd>{operations.health.emailConfigured?'Configured':'Not configured'}</dd><dt>Original publication</dt><dd>{operations.health.publicationConfigured?'Configured; separate authority required':'Native-only / not configured'}</dd><dt>Instance policies</dt><dd>{operations.health.instancePoliciesConfigured?'Configured':'Operator setup is incomplete'}</dd></dl><a class="underline" href="/about">Review operator and policy information</a></section>
 <section class="space-y-3"><h2 class="text-xl font-semibold">Unresolved publications ({operations.publicationCount})</h2>{#if !operations.publicationCount}<p>No unresolved publication commands were found.</p>{/if}{#each operations.pendingPublications as row}<article class="rounded border p-4"><h3 class="font-semibold">{row.kind} · {row.state==='source_accepted'?'Source accepted, local completion pending':'Original outcome must be checked'}</h3><p>{row.nextStep}</p><details><summary>Recovery reference</summary><p>{row.reference} · target {row.target} · last changed {new Date(row.updatedAt).toLocaleString()}</p></details></article>{/each}{#if operations.publicationCount>50}<p>Showing the oldest 50. Use the supported operator inventory for the complete backlog.</p>{/if}</section>
 <section class="space-y-3"><h2 class="text-xl font-semibold">Blocked or started schedules ({operations.scheduleCount})</h2>{#if !operations.scheduleCount}<p>No blocked or starting schedules were found.</p>{/if}{#each operations.blockedSchedules as row}<article class="rounded border p-4"><h3 class="font-semibold">{row.state==='starting'?'Publication has started':'Scheduled work is blocked'}</h3><p>{row.nextStep}</p><details><summary>Job reference</summary><p>{row.reference} · {new Date(row.updatedAt).toLocaleString()}</p></details></article>{/each}</section>{/if}
 <section class="rounded border p-4 space-y-3"><h2 class="text-xl font-semibold">Safe recovery guide</h2><ol class="list-decimal pl-5 space-y-2"><li>Identify the existing job using its recovery reference and saved state. Keep its original inputs and receipt.</li><li>If a command is prepared or started, treat the outcome as uncertain. The original operator must inspect the existing command and source receipt before deciding what can be resumed.</li><li>If the source accepted it, reconcile that exact command. Do not create a replacement publication or new identity to get past a conflict.</li><li>For a blocked schedule that has not started, the contributor can resolve the named prerequisite and use only the supported reviewed retry flow.</li><li>For withdrawn source content, native staff may not override the original service. Use the original operator’s separately authorized review or repair procedure.</li></ol><p><strong>Authority boundary:</strong> native administrators manage this instance’s accounts and local workflow. Original-service operators separately manage admission, publishers, peers, signing and storage. A native staff role is not an operator credential.</p><details><summary>Operator handoff checklist</summary><ul class="list-disc pl-5"><li>Verify configuration and schema with the supported read-only verification command.</li><li>Confirm backups are readable and restoration has been tested in an isolated environment before changing production.</li><li>Review pending command and scheduled-job receipts together. Record unresolved outcomes without replaying them.</li><li>Use the reviewed People and access workflow for native administrator handoff. Do not share passwords or private keys here.</li><li>Update the responsible operator, support contact and policy configuration before opening registration or uploads.</li></ul></details></section>
</section>
